export function defineTool(def){if(!def||!def.name)throw new Error('defineTool: name required');if(!def.description)throw new Error('defineTool: description required');if(!def.parameters)throw new Error('defineTool: parameters required');if(!def.output)throw new Error('defineTool: output required');if(typeof def.execute!=='function')throw new Error('defineTool: execute required');return Object.freeze({kind:'dsh-tool',...def})}
